use std::sync::{Arc, Mutex};                 // state inside the lock

pub struct Counter { inner: Arc<Mutex<(i64, u64)>> }
impl Counter {
    pub fn add(&self, delta: i64) {
        let mut g = self.inner.lock().unwrap();  // only path to the data
        g.0 += delta;
        g.1 += 1;
    }                                            // g drops -> unlocked
    pub fn snapshot(&self) -> (i64, u64) { *self.inner.lock().unwrap() }
}

