pub struct Db { inner: Arc<tokio::sync::Mutex<Connection>> }

impl Db {
    pub async fn query(&self, sql: &str) -> Row {
        let mut conn = self.inner.lock().await;  // yields, does not block
        conn.execute(sql).await
    }
}
